def test_set_3d_document_settings_logic(input_data: dict, mock_response: dict):
    # 1. ARRANGE
    command_group = TapirNavigatorCommands(core=MagicMock())
    command_group._core.post_tapir_command.return_value = mock_response

    # 2. ACT
    kwargs = {camel_to_snake(k): v for k, v in input_data.items()}
    result = command_group.set_3d_document_settings(**kwargs)

    # 3. ASSERT
    command_group._core.post_tapir_command.assert_called_once()
    args, _ = command_group._core.post_tapir_command.call_args
    assert args[0] == 'Set3DDocumentSettings'
    expected_payload = commands.Set3DDocumentSettingsParameters.model_validate(input_data).model_dump(mode='json', by_alias=True, exclude_none=True)
